// Process portfolio company data
const portfolioCompanies = $input.item.json;

// If no data, return empty
if (!portfolioCompanies || !Array.isArray(portfolioCompanies)) {
  return { json: { success: false, error: 'No portfolio company data found' } };
}

// Calculate portfolio metrics
const totalCompanies = portfolioCompanies.length;
let activeCompanies = 0;
let exitedCompanies = 0;
let acquiredCompanies = 0;
let ipoCompanies = 0;
let failedCompanies = 0;

// Count by sector
const sectorCounts = {};

// Count by stage
const stageCounts = {};

// Count by investment year
const yearCounts = {};

// Calculate metrics
portfolioCompanies.forEach(company => {
  // Count by status
  const status = company.status || 'Unknown';
  if (status.toLowerCase() === 'active') activeCompanies++;
  if (status.toLowerCase().includes('exit')) exitedCompanies++;
  if (status.toLowerCase().includes('acquired')) acquiredCompanies++;
  if (status.toLowerCase().includes('ipo')) ipoCompanies++;
  if (status.toLowerCase().includes('fail')) failedCompanies++;

  // Count by sector
  const sector = company.sector || 'Unknown';
  sectorCounts[sector] = (sectorCounts[sector] || 0) + 1;

  // Count by stage
  const stage = company.stage || 'Unknown';
  stageCounts[stage] = (stageCounts[stage] || 0) + 1;

  // Count by investment year
  if (company.initialInvestmentDate) {
    const year = new Date(company.initialInvestmentDate).getFullYear();
    yearCounts[year] = (yearCounts[year] || 0) + 1;
  }
});

// Calculate success rate
const successRate = totalCompanies > 0 ? Math.round((exitedCompanies / totalCompanies) * 100) : 0;

// Format results
const portfolioMetrics = {
  totalCompanies,
  activeCompanies,
  exitedCompanies,
  acquiredCompanies,
  ipoCompanies,
  failedCompanies,
  successRate,
  sectorDistribution: JSON.stringify(sectorCounts),
  stageDistribution: JSON.stringify(stageCounts),
  yearDistribution: JSON.stringify(yearCounts),
  lastUpdated: new Date().toISOString()
};

return { json: portfolioMetrics };

// Process investment data
const investments = $input.item.json;

// If no data, return empty
if (!investments || !Array.isArray(investments)) {
  return { json: { success: false, error: 'No investment data found' } };
}

// Calculate investment metrics
let totalInvested = 0;
let totalReturned = 0;
let unrealizedValue = 0;

// Count by round type
const roundCounts = {};

// Track investments by year
const investmentsByYear = {};

// Calculate metrics
investments.forEach(investment => {
  // Sum investment amounts
  const amount = parseFloat(investment.amount) || 0;
  totalInvested += amount;

  // Sum returns
  const returned = parseFloat(investment.returned) || 0;
  totalReturned += returned;

  // Sum unrealized value
  const unrealized = parseFloat(investment.unrealizedValue) || 0;
  unrealizedValue += unrealized;

  // Count by round type
  const roundType = investment.roundType || 'Unknown';
  roundCounts[roundType] = (roundCounts[roundType] || 0) + 1;

  // Track by year
  if (investment.date) {
    const year = new Date(investment.date).getFullYear();
    if (!investmentsByYear[year]) {
      investmentsByYear[year] = {
        count: 0,
        amount: 0
      };
    }
    investmentsByYear[year].count++;
    investmentsByYear[year].amount += amount;
  }
});

// Calculate total value
const totalValue = totalReturned + unrealizedValue;

// Calculate TVPI (Total Value to Paid-In)
const tvpi = totalInvested > 0 ? (totalValue / totalInvested).toFixed(2) : 0;

// Calculate DPI (Distributions to Paid-In)
const dpi = totalInvested > 0 ? (totalReturned / totalInvested).toFixed(2) : 0;

// Calculate RVPI (Remaining Value to Paid-In)
const rvpi = totalInvested > 0 ? (unrealizedValue / totalInvested).toFixed(2) : 0;

// Format results
const investmentMetrics = {
  totalInvested,
  totalReturned,
  unrealizedValue,
  totalValue,
  tvpi,
  dpi,
  rvpi,
  totalInvestments: investments.length,
  roundDistribution: JSON.stringify(roundCounts),
  investmentsByYear: JSON.stringify(investmentsByYear),
  lastUpdated: new Date().toISOString()
};

return { json: investmentMetrics };

// Process fund performance data
const fundData = $input.item.json;

// If no data, return empty
if (!fundData || !Array.isArray(fundData)) {
  return { json: { success: false, error: 'No fund performance data found' } };
}

// Calculate fund metrics
const fundMetrics = {};
const fundReturns = {};
const fundComparisons = {};

// Process each fund
fundData.forEach(fund => {
  const fundName = fund.fundName || 'Unknown';

  // Store fund metrics
  fundMetrics[fundName] = {
    size: parseFloat(fund.fundSize) || 0,
    vintage: fund.vintage || 'Unknown',
    committed: parseFloat(fund.committed) || 0,
    called: parseFloat(fund.called) || 0,
    distributed: parseFloat(fund.distributed) || 0,
    nav: parseFloat(fund.nav) || 0,
    tvpi: parseFloat(fund.tvpi) || 0,
    dpi: parseFloat(fund.dpi) || 0,
    irr: parseFloat(fund.irr) || 0
  };

  // Store historical returns if available
  if (fund.quarterlyReturns) {
    try {
      fundReturns[fundName] = JSON.parse(fund.quarterlyReturns);
    } catch (e) {
      fundReturns[fundName] = {};
    }
  }

  // Store benchmark comparisons if available
  if (fund.benchmarkComparisons) {
    try {
      fundComparisons[fundName] = JSON.parse(fund.benchmarkComparisons);
    } catch (e) {
      fundComparisons[fundName] = {};
    }
  }
});

// Calculate aggregate metrics across all funds
let totalFundSize = 0;
let totalCommitted = 0;
let totalCalled = 0;
let totalDistributed = 0;
let totalNAV = 0;
let weightedTVPI = 0;
let weightedIRR = 0;
let totalWeight = 0;

Object.values(fundMetrics).forEach(fund => {
  totalFundSize += fund.size;
  totalCommitted += fund.committed;
  totalCalled += fund.called;
  totalDistributed += fund.distributed;
  totalNAV += fund.nav;

  // Calculate weighted metrics
  if (fund.size > 0) {
    weightedTVPI += fund.tvpi * fund.size;
    weightedIRR += fund.irr * fund.size;
    totalWeight += fund.size;
  }
});

// Calculate final weighted metrics
const avgTVPI = totalWeight > 0 ? (weightedTVPI / totalWeight).toFixed(2) : 0;
const avgIRR = totalWeight > 0 ? (weightedIRR / totalWeight).toFixed(2) : 0;

// Format results
const fundPerformanceMetrics = {
  totalFunds: fundData.length,
  totalFundSize,
  totalCommitted,
  totalCalled,
  totalDistributed,
  totalNAV,
  avgTVPI,
  avgIRR,
  callRatio: totalCommitted > 0 ? ((totalCalled / totalCommitted) * 100).toFixed(2) : 0,
  distributionRatio: totalCalled > 0 ? ((totalDistributed / totalCalled) * 100).toFixed(2) : 0,
  fundMetrics: JSON.stringify(fundMetrics),
  fundReturns: JSON.stringify(fundReturns),
  fundComparisons: JSON.stringify(fundComparisons),
  lastUpdated: new Date().toISOString()
};

return { json: fundPerformanceMetrics };

// Process deal flow data
const dealFlowData = $input.item.json;

// If no data, return empty
if (!dealFlowData || !Array.isArray(dealFlowData)) {
  return { json: { success: false, error: 'No deal flow data found' } };
}

// Get current date for filtering
const now = new Date();
const currentYear = now.getFullYear();
const currentMonth = now.getMonth();

// Filter for deals in current year
const currentYearDeals = dealFlowData.filter(deal => {
  if (!deal.date) return false;
  const dealDate = new Date(deal.date);
  return dealDate.getFullYear() === currentYear;
});

// Filter for deals in current quarter
const currentQuarter = Math.floor(currentMonth / 3) + 1;
const currentQuarterDeals = currentYearDeals.filter(deal => {
  if (!deal.date) return false;
  const dealDate = new Date(deal.date);
  const dealQuarter = Math.floor(dealDate.getMonth() / 3) + 1;
  return dealQuarter === currentQuarter;
});

// Filter for deals in current month
const currentMonthDeals = currentYearDeals.filter(deal => {
  if (!deal.date) return false;
  const dealDate = new Date(deal.date);
  return dealDate.getMonth() === currentMonth;
});

// Count deals by stage
const stageCount = {};
dealFlowData.forEach(deal => {
  const stage = deal.stage || 'Unknown';
  stageCount[stage] = (stageCount[stage] || 0) + 1;
});

// Count deals by source
const sourceCount = {};
dealFlowData.forEach(deal => {
  const source = deal.source || 'Unknown';
  sourceCount[source] = (sourceCount[source] || 0) + 1;
});

// Count deals by sector
const sectorCount = {};
dealFlowData.forEach(deal => {
  const sector = deal.sector || 'Unknown';
  sectorCount[sector] = (sectorCount[sector] || 0) + 1;
});

// Calculate conversion rates
const totalDeals = dealFlowData.length;
const pitchMeetings = dealFlowData.filter(deal => 
  deal.stage && deal.stage.toLowerCase().includes('pitch')).length;
const dueDiligence = dealFlowData.filter(deal => 
  deal.stage && deal.stage.toLowerCase().includes('diligence')).length;
const termSheet = dealFlowData.filter(deal => 
  deal.stage && deal.stage.toLowerCase().includes('term')).length;
const closed = dealFlowData.filter(deal => 
  deal.stage && deal.stage.toLowerCase().includes('closed')).length;

// Calculate conversion rates
const pitchToDDRate = pitchMeetings > 0 ? ((dueDiligence / pitchMeetings) * 100).toFixed(2) : 0;
const ddToTermRate = dueDiligence > 0 ? ((termSheet / dueDiligence) * 100).toFixed(2) : 0;
const termToCloseRate = termSheet > 0 ? ((closed / termSheet) * 100).toFixed(2) : 0;
const overallConversionRate = totalDeals > 0 ? ((closed / totalDeals) * 100).toFixed(2) : 0;

// Group deals by month for trend analysis
const dealsByMonth = {};
dealFlowData.forEach(deal => {
  if (!deal.date) return;
  const dealDate = new Date(deal.date);
  const yearMonth = `${dealDate.getFullYear()}-${String(dealDate.getMonth() + 1).padStart(2, '0')}`;

  if (!dealsByMonth[yearMonth]) {
    dealsByMonth[yearMonth] = {
      total: 0,
      byStage: {}
    };
  }

  dealsByMonth[yearMonth].total++;

  const stage = deal.stage || 'Unknown';
  dealsByMonth[yearMonth].byStage[stage] = (dealsByMonth[yearMonth].byStage[stage] || 0) + 1;
});

// Format results
const dealFlowMetrics = {
  totalDeals,
  currentYearDeals: currentYearDeals.length,
  currentQuarterDeals: currentQuarterDeals.length,
  currentMonthDeals: currentMonthDeals.length,
  pitchMeetings,
  dueDiligence,
  termSheet,
  closed,
  pitchToDDRate,
  ddToTermRate,
  termToCloseRate,
  overallConversionRate,
  stageDistribution: JSON.stringify(stageCount),
  sourceDistribution: JSON.stringify(sourceCount),
  sectorDistribution: JSON.stringify(sectorCount),
  dealsByMonth: JSON.stringify(dealsByMonth),
  lastUpdated: new Date().toISOString()
};

return { json: dealFlowMetrics };

// Combine all metrics into a single dashboard dataset
