const investmentMetrics = $input.all()[1].json;
const fundMetrics = $input.all()[2].json;
const dealFlowMetrics = $input.all()[3].json;

// Create dashboard data object
const dashboardData = {
  generatedAt: new Date().toISOString(),
  portfolio: portfolioMetrics,
  investments: investmentMetrics,
  funds: fundMetrics,
  dealFlow: dealFlowMetrics
