// Add summary metrics for quick access
const summaryMetrics = {
  totalPortfolioCompanies: portfolioMetrics.totalCompanies || 0,
  activePortfolioCompanies: portfolioMetrics.activeCompanies || 0,
  exitedCompanies: portfolioMetrics.exitedCompanies || 0,
  totalInvested: investmentMetrics.totalInvested || 0,
  totalValue: investmentMetrics.totalValue || 0,
  overallTVPI: investmentMetrics.tvpi || 0,
  avgFundIRR: fundMetrics.avgIRR || 0,
  totalDeals: dealFlowMetrics.totalDeals || 0,
  currentYearDeals: dealFlowMetrics.currentYearDeals || 0,
  dealConversionRate: dealFlowMetrics.overallConversionRate || 0
};

dashboardData.summary = summaryMetrics;

return { json: dashboardData };

// Generate dashboard HTML
const dashboardData = $input.item.json;

// Format currency function
const formatCurrency = (amount) => {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  }).format(amount);
