      type: 'pie',
      data: {
        labels: ['Active', 'Exited', 'Failed'],
        datasets: [{
          data: [portfolioData.activeCompanies, portfolioData.exitedCompanies, portfolioData.failedCompanies],
          backgroundColor: ['#4e73df', '#1cc88a', '#e74a3b']
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: { position: 'bottom' },
