    });

    // Portfolio Sector Chart
    new Chart(document.getElementById('portfolioSectorChart'), {
      type: 'pie',
      data: {
        labels: Object.keys(sectorDistribution),
        datasets: [{
          data: Object.values(sectorDistribution),
          backgroundColor: ['#4e73df', '#1cc88a', '#36b9cc', '#f6c23e', '#e74a3b', '#858796']
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: { position: 'bottom' },
          title: { display: true, text: 'Portfolio by Sector' }
        }
      }
    });

    // Portfolio Stage Chart
