        plugins: {
          legend: { position: 'bottom' },
          title: { display: true, text: 'Portfolio by Stage' }
        }
      }
    });

    // Investments by Year Chart
    const yearLabels = Object.keys(investmentsByYear).sort();
    const yearAmounts = yearLabels.map(year => investmentsByYear[year].amount);
    const yearCounts = yearLabels.map(year => investmentsByYear[year].count);

    new Chart(document.getElementById('investmentsByYearChart'), {
      type: 'bar',
      data: {
        labels: yearLabels,
        datasets: [
          {
            label: 'Amount Invested',
            data: yearAmounts,
            backgroundColor: '#4e73df',
            yAxisID: 'y'
